contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single-parameter test: amount that owner asks C to send back
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // require a strictly positive amount and ensure this contract can receive that amount
        require(amount > 0, "amount must be > 0");
        // ensure C has at least `amount` so transfer can succeed without reverting due to lack of funds
        require(address(c).balance >= amount, "C must have enough balance");

        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // Owner (this contract) instructs C to send `amount` to this contract
        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;

        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // General rule: C's balance decreases by exactly `amount` and this contract's balance increases by exactly `amount`.
        assert(beforeCBalance - afterCBalance == amount && afterThisBalance - beforeThisBalance == amount);
    }

    receive() external payable { }
}

