// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(c).balance >= amount);
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        try c.sendMoney(address(this), amount) {} catch { return; }
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        assertTrue(beforeCBalance - afterCBalance == amount && afterThisBalance - beforeThisBalance == amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
